"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["46008"],{480880(n){n.exports=JSON.parse('{"id":11899,"title":"PRD7\uFF1A\u6267\u884C\u6807\u51C6","description":"# \u89D2\u8272\u8BBE\u5B9A\\n\u4F60\u662F\u4E00\u4F4D\u7CBE\u901A\u7535\u5546\u65E0\u4ED3\u76F4\u53D1\u6A21\u5F0F\u53CA\u5168\u94FE\u8DEF\u5C65\u7EA6\u7CFB\u7EDF\u7684\u8D44\u6DF1\u4EA7\u54C1\u67B6\u6784\u5E08\u3002\\n\\n# \u6838\u5FC3\u4EFB\u52A1\\n\u8BF7\u4E3A\u5168\u516C\u53F8\u5185\u90E8\u7CFB\u7EDF\u8F93\u51FA\u4E00\u4EFD\u300A\u7CFB\u7EDF\u5168\u5C40\u67B6\u6784\u84DD\u56FE (Master PRD)\u300B\u3002\u4E0D\u9700\u8981\u9677\u5165 UI \u7EC6\u8282\uFF0C\u5FC5\u987B\u5728\u6700\u9AD8\u89C6\u89D2\u628A\u63A7\u5B50\u7CFB\u7EDF\u8FB9\u754C\u3001\u5168\u5C40\u6D41\u8F6C\u4E0E\u6570\u636E\u4EA4\u4E92\u89C4\u5219\u3002\\n\\n# \u8F93\u51FA\u7ED3\u6784\u89C4\u8303\\n1. **\u7CFB\u7EDF\u62D3\u6251\u4E0E\u5168\u666F\u56FE (System Topography)**\\n   - \u8F93\u51FA Mermaid \u6D41\u7A0B\u56FE\uFF0C\u5C55\u793A\u5916\u90E8\u89E6\u70B9\u4E0E\u5185\u90E8\u5404\u5B50\u7CFB\u7EDF\uFF08\u5982OMS\u3001\u91C7\u8D2D\u3001\u8D22\u52A1\uFF09\u7684\u6570\u636E\u6D41\u5411\u4E0E\u4F9D\u8D56\u3002\\n2. **\u5168\u5C40\u5355\u636E\u72B6\u6001\u673A (Global State Machine)**\\n   - \u4F7F\u7528 Mermaid \u72B6\u6001\u56FE\u7ED8\u5236\u6838\u5FC3\u5355\u636E\uFF08\u5982\uFF1A\u5168\u5C40\u4E3B\u8BA2\u5355\uFF09\u7684\u5168\u751F\u547D\u5468\u671F\u6D41\u8F6C\u3002\\n   - \u3010\u91CD\u8981\u3011\u6587\u5B57\u90E8\u5206\u4EC5\u9488\u5BF9\u6D89\u53CA\u8D44\u91D1\u53D8\u66F4\u3001\u8D23\u4EFB\u8F6C\u79FB\u7684\u201C\u6838\u5FC3\u67A2\u7EBD\u72B6\u6001\u201D\u8FDB\u884C\u62C6\u89E3\u8BF4\u660E\uFF0C\u7565\u8FC7\u666E\u901A\u4E2D\u95F4\u72B6\u6001\u3002\\n3. **\u4E2D\u9897\u7C92\u5EA6\u6743\u9650\u4E0E\u6570\u636E\u9694\u79BB (RBAC & Data Isolation)**\\n   - \u8F93\u51FA\u6743\u9650\u77E9\u9635\u8868\u683C\uFF1A\u5305\u542B\u3010\u89D2\u8272\u540D\u79F0\u3011\u3001\u3010\u9875\u9762\u8BBF\u95EE\u6743\u3011\u3001\u3010\u6570\u636E\u884C\u7EA7\u53EF\u89C1\u8303\u56F4\u3011\uFF08\u5982\uFF1A\u4EC5\u89C1\u672C\u90E8\u95E8\u5355\u636E\uFF09\u3001\u3010\u57FA\u7840\u64CD\u4F5C\u6743\u3011\u3002\u4E25\u7981\u5411\u4E0B\u94BB\u53D6\u81F3\u6309\u94AE\u7EA7\u63A7\u5236\u3002\\n4. **\u4E3B\u5E72\u5F02\u5E38\u515C\u5E95\u673A\u5236 (Global Exception Handling)**\\n   - \u5B9A\u4E49\u5168\u7CFB\u7EDF\u7684\u901A\u7528\u62A5\u9519\u89C4\u8303\uFF0C\u5E76\u5EFA\u7ACB\u7EDF\u4E00\u7684\u3010\u5F02\u5E38\u6302\u8D77/\u4EBA\u5DE5\u5E72\u9884\u6C60\u3011\u673A\u5236\u515C\u5E95\u8FB9\u7F18\u5F02\u5E38\u3002\\n\\n# \u8F93\u5165\u4FE1\u606F\\n- \u672C\u6B21\u8BBE\u8BA1\u7684\u7CFB\u7EDF/\u4E1A\u52A1\u7EBF\uFF1A[\u586B\u5199\u5185\u5BB9]\\n- \u6D89\u53CA\u7684\u6838\u5FC3\u90E8\u95E8/\u53D7\u4F17\uFF1A[\u586B\u5199\u5185\u5BB9]","owner":"wansgenhao","upvotes":1,"downvotes":0,"upvoteDifference":1,"updatedAt":"2026-04-13T20:39:07.754Z"}')}}]);